  USING ( SELECT 'GET_ADMIN_GROUP_MEASURE' AS LOOKUP_TYPE, 'DM Planner (W/S)' AS SEGMENT1, 'DMF0082' AS SEGMENT2, '81_UC' AS SEGMENT3, 'AS_In_Req' AS SEGMENT4, '-' AS SEGMENT5, 25 AS DISPLAY_SEQ, 'Y' AS VALID_YN, NULL AS DESCRIPTION, NULL AS ATTRIBUTE1, NULL AS ATTRIBUTE2, NULL AS ATTRIBUTE3, NULL AS ATTRIBUTE4, NULL AS ATTRIBUTE5, 'admin' AS CREATED_BY, TO_DATE('2026-08-11 18:28:59','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'admin' AS LAST_UPDATED_BY, TO_DATE('2026-08-11 18:28:59','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL ) S
