  USING ( SELECT 'GET_ADMIN_GROUP_MEASURE' AS LOOKUP_TYPE, 'SCM PI Admin' AS SEGMENT1, 'DMF0082' AS SEGMENT2, '82' AS SEGMENT3, 'LOC' AS SEGMENT4, '-' AS SEGMENT5, 7 AS DISPLAY_SEQ, 'Y' AS VALID_YN, '[E20260814-CURMEASURE] No.41 — DM_UI_EDITABLE_MEASURE(AS-IS) 등재 사업부 grant 보강' AS DESCRIPTION, NULL AS ATTRIBUTE1, NULL AS ATTRIBUTE2, NULL AS ATTRIBUTE3, NULL AS ATTRIBUTE4, NULL AS ATTRIBUTE5, 'admin' AS CREATED_BY, TO_DATE('2026-08-14 05:45:18','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'admin' AS LAST_UPDATED_BY, TO_DATE('2026-08-14 05:45:18','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL ) S
     ON ( T.LOOKUP_TYPE = S.LOOKUP_TYPE AND T.SEGMENT1 = S.SEGMENT1 AND T.SEGMENT2 = S.SEGMENT2 AND T.SEGMENT3 = S.SEGMENT3 AND T.SEGMENT4 = S.SEGMENT4 AND T.SEGMENT5 = S.SEGMENT5 )
   WHEN MATCHED THEN UPDATE SET T.DISPLAY_SEQ = S.DISPLAY_SEQ, T.VALID_YN = S.VALID_YN, T.DESCRIPTION = S.DESCRIPTION, T.ATTRIBUTE1 = S.ATTRIBUTE1, T.ATTRIBUTE2 = S.ATTRIBUTE2, T.ATTRIBUTE3 = S.ATTRIBUTE3, T.ATTRIBUTE4 = S.ATTRIBUTE4, T.ATTRIBUTE5 = S.ATTRIBUTE5, T.LAST_UPDATED_BY = 'admin', T.LAST_UPDATE_DATE = SYSDATE
   WHEN NOT MATCHED THEN INSERT (LOOKUP_TYPE, SEGMENT1, SEGMENT2, SEGMENT3, SEGMENT4, SEGMENT5, DISPLAY_SEQ, VALID_YN, DESCRIPTION, ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE) VALUES (S.LOOKUP_TYPE, S.SEGMENT1, S.SEGMENT2, S.SEGMENT3, S.SEGMENT4, S.SEGMENT5, S.DISPLAY_SEQ, S.VALID_YN, S.DESCRIPTION, S.ATTRIBUTE1, S.ATTRIBUTE2, S.ATTRIBUTE3, S.ATTRIBUTE4, S.ATTRIBUTE5, S.CREATED_BY, S.CREATION_DATE, S.LAST_UPDATED_BY, S.LAST_UPDATE_DATE);
END;
/

